import{_ as o,o as e,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const u=JSON.parse('{"title":"FormInput（输入框原语）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/form/docs/README-FormInput.md","filePath":"docs/core/src/components/form/docs/README-FormInput.md"}'),s={name:"docs/core/src/components/form/docs/README-FormInput.md"};function r(l,t,i,c,n,p){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="forminput-输入框原语" tabindex="-1">FormInput（输入框原语） <a class="header-anchor" href="#forminput-输入框原语" aria-label="Permalink to &quot;FormInput（输入框原语）&quot;">​</a></h1><blockquote><p>el-input 全透传包装 + password 形态浏览器自动填充治理（<code>passwordAutoComplete</code> prop）。除治理点外 props / slots 全量透传 el-input，零收窄。 范式页：<code>apps/reference/src/pages/form/input/showcase/</code>（五形态对照 + 组合链路）。</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>password 形态的浏览器自动填充治理点</strong>：apiKey / 账号密码录入等非登录表单字段被 Chrome 误填时，用 <code>passwordAutoComplete</code> 治理</li><li><strong>独立裸用当</strong>：需要密码形态且与浏览器密码管理器交互受控的输入框</li><li><strong>何时不用</strong>：普通输入直接用 el-input；真登录页<strong>接受</strong>浏览器填充（用户主动保存 = 期望被填，拦它违背设计意图）</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">FormInput</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;secret&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;password&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> password-auto-complete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;api-key&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li>字符串值（<code>api-key</code> / <code>new-password</code> / <code>off</code>）→ 密码输入框 <code>autocomplete</code> 设为此值。<strong>默认推荐 <code>api-key</code></strong>——规范外词条 Chrome 不识别，实测全程未触发直接填充；<code>off</code> 是 el-input 密码形态默认值、Chrome 有意无视（不可靠）；<code>new-password</code> 实测出现过直接填充</li><li><code>number N</code> → 不设置 autocomplete；透传 el-input 的 type 初始 <code>text</code>（无密码语义不触发填充），延迟 N ms 后恢复 <code>password</code>（避开 Chrome 加载期 autofill 探测窗口；点击填充拦不住，属浏览器正常交互）。text 窗口内组件内部屏蔽 EP <code>show-password</code> 强制坑（EP <code>showPassword=true</code> 会强制 type=password，恢复后显隐照常）</li><li>不传 → 不设置 autocomplete（保持 el-input 默认行为）</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：<code>passwordAutoComplete</code> 不传即为普通 el-input 包装</strong>。以下按需开：</li><li><code>passwordAutoComplete=&quot;api-key&quot;</code>：非登录表单密码字段防填充首选（规范外词条最可靠）</li><li><code>passwordAutoComplete={N}</code>（number）：需要连「加载填充」也拦截时（api-key 词条已拦不住时）；N=0 即挂载即切</li><li><code>show-password</code>：显隐切换照常透传（number 延迟窗口内被组件内部屏蔽、恢复后可用）</li><li><strong>影分身（表头漏斗）用 <code>FormInputShadowClone</code></strong>（本组件 + 影分身包装，薄包装纯粹性——影分身能力不内嵌本组件）：列表页表格头预埋容器内显示漏斗图标，点击 popover 弹输入框，同一 v-model 与本体同源同步（与 FormSelectShadowClone 统一漏斗语义；「表头漏斗 = 点这里筛选」）</li><li>实测反模式（[MUST NOT] 重复踩）：<code>autocomplete=&quot;off&quot;</code>（Chrome 有意无视）/ <code>new-password</code>（有过直接填充记录）/ text→mounted 立即切换（Chrome 异步 autofill 补填）/ trap input（Chrome 可见性检查穿透）——全部实测证伪，组件只提供上述两个可靠机制</li></ul><h2 id="依赖关系" tabindex="-1">依赖关系 <a class="header-anchor" href="#依赖关系" aria-label="Permalink to &quot;依赖关系&quot;">​</a></h2><ul><li>form 族内部组件，无跨族依赖（仅透传 el-input）；影分身版 <code>FormInputShadowClone</code> 依赖内部件 <code>FormShadowCloneDispatch</code> → display 族 <code>ShadowClone</code>（详见 README-FormShadowCloneDispatch.md）</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>string</code></td><td>—</td><td>透传 el-input（显式声明以判定密码形态）</td></tr><tr><td><code>showPassword</code></td><td><code>boolean</code></td><td>—</td><td>透传 el-input 显隐切换（同上）</td></tr><tr><td><code>passwordAutoComplete</code></td><td><code>&quot;api-key&quot; | &quot;new-password&quot; | &quot;off&quot; | number</code></td><td>—</td><td>密码形态自动填充治理（见上）</td></tr><tr><td>其余</td><td>—</td><td>—</td><td>全量 <code>$attrs</code> 透传 el-input（v-model / placeholder / clearable / 插槽等）</td></tr></tbody></table><h3 id="forminputshadowclone-影分身版" tabindex="-1">FormInputShadowClone（影分身版） <a class="header-anchor" href="#forminputshadowclone-影分身版" aria-label="Permalink to &quot;FormInputShadowClone（影分身版）&quot;">​</a></h3><blockquote><p>内部经 <code>FormShadowCloneDispatch</code> 实现：default 与 clone 两插槽各写一份 <code>&lt;FormInput v-model=&quot;同一值&quot; /&gt;</code> 同源绑定驱动双处视图一致；高亮判定在<strong>本组件内部</strong>（默认规则 + <code>isHighlighted</code> 覆盖）→ 经 dispatch <code>highlighted</code> 展示在漏斗 + 插槽作用域暴露。</p></blockquote><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>modelValue</code></td><td><code>string | number</code></td><td>—</td><td>v-model（透传 FormInput；本体与分身弹层同源）</td></tr><tr><td><code>shadowClone</code></td><td><code>boolean</code></td><td><code>false</code></td><td>影分身开关（本体 + 分身 label+漏斗，点击 popover 弹输入框，同一 v-model 同源同步）</td></tr><tr><td><code>teleportTo</code></td><td><code>string | Element</code></td><td>—</td><td>分身目标容器（表头预埋唯一选择器；<code>shadowClone</code> 时生效，未配置不分身）</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td>—</td><td>分身位字段文字（表头列名；label + 漏斗整块展示、高亮整块——表格 headerRender 只需留 teleportTo 容器，列名由分身自带）</td></tr><tr><td><code>isHighlighted</code></td><td><code>(value: unknown) =&gt; boolean</code></td><td>默认判定</td><td>分身高亮判定方法（非必传），入参 modelValue；默认 = 非 <code>null</code> / 非 <code>undefined</code> / 非空字符串 → 高亮（label + 漏斗整块）</td></tr><tr><td>其余</td><td>—</td><td>—</td><td>全量 <code>$attrs</code> 透传 FormInput（密码治理等能力完整继承）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>语义</th></tr></thead><tbody><tr><td>全部</td><td>透传 el-input 插槽（prefix / suffix / prepend / append 等）</td></tr></tbody></table>',21)])])}const m=o(s,[["render",r]]);export{u as __pageData,m as default};
